"""Money arithmetic for invoices."""
from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def _decimal(value):
    return value if isinstance(value, Decimal) else Decimal(str(value))


def line_total(qty, unit_price):
    return (_decimal(qty) * _decimal(unit_price)).quantize(CENT, rounding=ROUND_HALF_UP)


def total(lines):
    return sum(
        (line_total(line["qty"], line["unit_price"]) for line in lines),
        Decimal("0.00"),
    )

